import { test, expect } from '@playwright/test';
import * as fs from 'fs';
import * as path from 'path';

test.describe('File Upload Functionality', () => {
  const testFilePath = path.join(__dirname, 'test-file.txt');
  const testFileName = 'test-file.txt';
  const testFileContent = 'This is a test file for upload functionality.';

  test.beforeEach(async ({ page }) => {
    // Create a test file if it doesn't exist
    if (!fs.existsSync(testFilePath)) {
      fs.writeFileSync(testFilePath, testFileContent);
    }

    // Navigate to the upload page
    await page.goto('https://the-internet.herokuapp.com/upload');
  });

  test('should upload a small text file and confirm upload success', async ({ page }) => {
    // Set the file input value
    const fileInput = page.locator('#file-upload');
    await fileInput.setInputFiles(testFilePath);

    // Click the submit button
    const submitButton = page.locator('#file-submit');
    await submitButton.click();

    // Wait for navigation to complete
    await page.waitForURL('**/upload_handler');

    // Verify the heading "File Uploaded!" is present
    const heading = page.getByRole('heading', { name: 'File Uploaded!' });
    await expect(heading).toBeVisible();

    // Verify the uploaded file name is shown in the uploaded-files section
    const uploadedFiles = page.locator('#uploaded-files');
    await expect(uploadedFiles).toContainText(testFileName);
  });

  test('should display uploaded filename in the correct location', async ({ page }) => {
    // Upload the file
    const fileInput = page.locator('#file-upload');
    await fileInput.setInputFiles(testFilePath);

    // Submit the form
    const submitButton = page.locator('#file-submit');
    await submitButton.click();

    // Wait for the success page
    await page.waitForURL('**/upload_handler');

    // Verify the uploaded-files section contains the exact filename
    const uploadedFilesSection = page.locator('#uploaded-files');
    const fileNameText = await uploadedFilesSection.textContent();
    expect(fileNameText).toContain(testFileName);

    // Verify the section is visible and not empty
    await expect(uploadedFilesSection).toBeVisible();
    await expect(uploadedFilesSection).not.toBeEmpty();
  });

  test('should verify file upload page elements are present before upload', async ({ page }) => {
    // Verify the file input element exists
    const fileInput = page.locator('#file-upload');
    await expect(fileInput).toBeVisible();

    // Verify the submit button exists
    const submitButton = page.locator('#file-submit');
    await expect(submitButton).toBeVisible();

    // Verify the submit button is clickable
    await expect(submitButton).toBeEnabled();
  });
});
